// Conteúdo autoral. Os resultados abaixo são oráculos declarados, nunca calculados pelo gabarito.
import fs from 'node:fs';
const records=[];let topic,level;
function group(t,l){topic=t;level=l;}
function add(title,description,source,expected,hint){
 const answers=[]; const code=source.replace(/«([\s\S]*?)»/g,(_,a)=>{const i=answers.length;answers.push(a.split('¦'));return `___${i}___`;});
 if(!answers.length)throw Error(title);
 const number=records.filter(e=>e.topic===topic&&e.level===level).length+1;
 records.push({id:`${topic}-${level}-${String(number).padStart(2,'0')}`,topic,level,number,title,description:description+' Preencha somente os trechos marcados; os parênteses e as chaves fora da lacuna já fazem parte do código.',code,answers,expected:JSON.stringify(expected),hint,explanation:hint});
}
function ret(title,goal,body,calls,expected,hint){add(title,goal,body+'\nconsole.log(JSON.stringify('+calls+'));',expected,hint);}
group('return','easy');
ret('Devolver o cumprimento','Retorne a saudação montada, sem imprimir dentro da função.','function saudar(nome) {\n  «return» "Olá, " + nome;\n}','[saudar("Ana"), saudar("Bia")]', ['Olá, Ana','Olá, Bia'],'return entrega um valor ao chamador; console.log apenas o exibe.');
ret('Área de um retângulo','Retorne o produto da base pela altura.','function area(base, altura) {\n  return «base * altura¦altura * base»;\n}','[area(3,4),area(0,5)]',[12,0],'A área usa multiplicação; o zero é um resultado válido.');
ret('Minutos em segundos','Devolva a conversão de minutos para segundos.','function segundos(minutos) {\n  return «minutos * 60¦60 * minutos»;\n}','[segundos(2),segundos(0)]',[120,0],'Cada minuto tem 60 segundos.');
ret('Retorno de um booleano','Retorne true para números ímpares, incluindo negativos.','function impar(n) {\n  return «n % 2 !== 0¦n % 2 != 0»;\n}','[impar(3),impar(4),impar(-3)]',[true,false,true],'Resto diferente de zero também reconhece ímpares negativos.');
ret('Última letra','Retorne a última letra; em texto vazio, retorne string vazia.','function ultima(texto) {\n  return texto.length ? «texto[texto.length - 1]¦texto.at(-1)» : "";\n}','[ultima("node"),ultima("")]',['e',''],'O último índice é length - 1.');
ret('Retorno de objeto','Complete a instrução que devolve um objeto com nome e idade.','function perfil(nome, idade) {\n  «return» { nome, idade };\n}','[perfil("Lia",20),perfil("Ivo",0)]',[{nome:'Lia',idade:20},{nome:'Ivo',idade:0}],'return pode devolver objetos, além de valores primitivos.');
ret('Par de vizinhos','Retorne um array contendo o antecessor e o sucessor.','function vizinhos(n) {\n  return «[n - 1, n + 1]»;\n}','[vizinhos(5),vizinhos(0)]',[[4,6],[-1,1]],'O retorno deve preservar a ordem antecessor, sucessor.');
ret('Encerrar antes do log','Saia da função antes de acrescentar a segunda marca ao histórico.','const marcas = [];\nfunction parar() {\n  marcas.push("entrou");\n  «return»;\n  marcas.push("continuou");\n}\nparar();','marcas',['entrou'],'return sem expressão encerra a execução e devolve undefined.');
ret('Valor padrão na ausência','Retorne zero apenas para null ou undefined.','function quantidade(valor) {\n  return «valor ?? 0»;\n}','[quantidade(null),quantidade(0),quantidade(7)]',[0,0,7],'?? preserva valores válidos como zero.');
ret('Celsius para Fahrenheit','Retorne a temperatura convertida pela fórmula C × 9/5 + 32.','function fahrenheit(c) {\n  return «c * 9 / 5 + 32»;\n}','[fahrenheit(0),fahrenheit(100)]',[32,212],'A multiplicação e a divisão acontecem antes da soma.');
ret('Nome sem bordas','Devolva o nome sem espaços externos.','function limpar(nome) {\n  return «nome.trim()»;\n}','[limpar(" Ana "),limpar("  ")]',['Ana',''],'trim devolve uma nova string.');
ret('Escolher o maior','Retorne o maior de dois valores, sem alterar os argumentos.','function maior(a,b) {\n  if (a > b) return a;\n  «return» b;\n}','[maior(2,9),maior(8,3),maior(4,4)]',[9,8,4],'Se o primeiro ramo não retorna, a função precisa de um retorno final.');
ret('Validar antes de dividir','Retorne null para divisor zero; nos demais casos, devolva o quociente.','function dividir(a,b) {\n  if (b === 0) «return null»;\n  return a / b;\n}','[dividir(8,2),dividir(5,0)]',[4,null],'O retorno antecipado impede a divisão por zero.');
ret('Comprimento útil','Retorne a quantidade de caracteres após retirar espaços externos.','function tamanho(texto) {\n  return «texto.trim().length»;\n}','[tamanho(" oi "),tamanho("")]',[2,0],'O comprimento deve ser medido no resultado de trim.');
ret('Desconto em reais','Retorne o preço menos o valor fixo de desconto.','function pagar(preco,desconto) {\n  return «preco - desconto»;\n}','[pagar(50,8),pagar(20,0)]',[42,20],'A expressão devolvida é uma subtração.');
ret('Retorno de includes','Devolva se o array contém o item procurado.','function contem(itens,item) {\n  return «itens.includes(item)»;\n}','[contem([1,2],2),contem([],2)]',[true,false],'includes já devolve o booleano necessário.');
ret('Primeiro item ou null','Use retorno antecipado quando não houver itens.','function primeiro(itens) {\n  if (!itens.length) «return null»;\n  return itens[0];\n}','[primeiro([]),primeiro([0,5])]',[null,0],'Array vazio é diferente de um array cujo primeiro valor é zero.');
ret('Montar caminho relativo','Devolva pasta e arquivo separados por uma barra.','function caminho(pasta,arquivo) {\n  return «pasta + "/" + arquivo»;\n}','[caminho("src","app.js"),caminho("test","a.js")]',['src/app.js','test/a.js'],'A função retorna a concatenação completa.');
ret('Retorno explícito em arrow','Uma arrow com chaves precisa de return para devolver o triplo.','const triplo = n => {\n  «return» n * 3;\n};','[triplo(2),triplo(-1)]',[6,-3],'Um corpo com chaves não tem retorno implícito.');
ret('Objeto de uma arrow','Complete o retorno explícito do objeto de status.','const status = () => {\n  return «{ ativo: true }»;\n};','status()',{ativo:true},'O objeto fica depois de return no mesmo corpo de função.');
ret('Retorno após cálculo local','Devolva a variável calculada dentro da função.','function perimetro(lado) {\n  const total = lado * 4;\n  return «total»;\n}','[perimetro(5),perimetro(0)]',[20,0],'Variáveis locais podem compor o valor retornado.');
ret('Preservar false','Retorne o próprio argumento, mesmo quando for false.','function identidade(valor) {\n  return «valor»;\n}','[identidade(false),identidade(0),identidade("")]',[false,0,''],'Não substitua valores falsy por um padrão.');
ret('Mesma referência','Retorne o objeto recebido, sem criar uma cópia.','function repassar(objeto) {\n  return «objeto»;\n}\nconst original = { x: 1 };','repassar(original) === original',true,'Retornar o argumento preserva a identidade da referência.');
ret('Cópia superficial','Devolva uma cópia rasa do objeto usando spread.','function copiar(objeto) {\n  return «{ ...objeto }»;\n}\nconst a = { x: 1 };\nconst b = copiar(a);','[b, b === a]',[{x:1},false],'Spread cria um novo objeto com as propriedades do original.');
ret('Arredondar para baixo','Retorne o número de caixas completas de seis unidades.','function caixas(unidades) {\n  return «Math.floor(unidades / 6)»;\n}','[caixas(13),caixas(5)]',[2,0],'floor descarta a parte fracionária da divisão.');
ret('Cláusula de guarda textual','Retorne vazio se o argumento não for string.','function gritar(valor) {\n  if (typeof valor !== "string") «return ""»;\n  return valor.toUpperCase();\n}','[gritar("oi"),gritar(2)]',['OI',''],'A guarda evita chamar um método de string em um número.');
ret('Retornar a soma em reduce','Complete o retorno do callback que acumula o total.','function somar(valores) {\n  return valores.reduce((total,n) => {\n    «return» total + n;\n  }, 0);\n}','[somar([1,2,3]),somar([])]',[6,0],'Cada callback deve devolver o acumulador da próxima etapa.');
ret('Função sem valor','Complete uma saída sem expressão e reconheça undefined.','function sair() {\n  «return»;\n}\nconst valor = sair();','typeof valor','undefined','Um return vazio não devolve null, mas undefined.');
ret('Formatar código com zeros','Retorne uma string de três posições, preenchida à esquerda.','function codigo(n) {\n  return «String(n).padStart(3, "0")»;\n}','[codigo(7),codigo(125)]',['007','125'],'Converta para string antes de aplicar padStart.');
ret('Retorno de sinal','Devolva -1, 0 ou 1 conforme o sinal do número.','function sinal(n) {\n  return «Math.sign(n)»;\n}','[sinal(-4),sinal(0),sinal(9)]',[-1,0,1],'Math.sign entrega a classificação numérica do sinal.');

group('return','medium');
ret('Busca com saída antecipada','Retorne o primeiro objeto ativo, ou null se nenhum estiver ativo.','function buscar(itens) {\n  for (const item of itens) {\n    if (item.ativo) «return item»;\n  }\n  return null;\n}','[buscar([{id:1,ativo:false},{id:2,ativo:true}]),buscar([])]',[{id:2,ativo:true},null],'Retornar dentro do laço encerra a função no primeiro encontro.');
