ret('Fábrica de multiplicadores','Devolva uma função que lembra o fator recebido.','function multiplicador(fator) {\n  return n => {\n    return «n * fator¦fator * n»;\n  };\n}\nconst vezes4 = multiplicador(4);','[vezes4(3),vezes4(0)]',[12,0],'A função retornada fecha sobre a variável fator.');
ret('Curto-circuito com cache','Devolva o valor em cache inclusive quando ele é zero.','const cache = new Map([["a",0]]);\nfunction ler(chave) {\n  if (cache.has(chave)) return «cache.get(chave)»;\n  return -1;\n}','[ler("a"),ler("b")]',[0,-1],'has distingue ausência de um valor falsy armazenado.');
ret('Contratos com resultado discriminado','Retorne um objeto de sucesso com o valor numérico.','function numero(texto) {\n  const n = Number(texto);\n  if (!Number.isFinite(n)) return { ok: false };\n  return «{ ok: true, valor: n }»;\n}','[numero("12"),numero("x")]',[{ok:true,valor:12},{ok:false}],'O consumidor distingue os ramos pela propriedade ok.');
ret('Particionar dados','Retorne os arrays positivos e não positivos em um objeto.','function separar(xs) {\n  const positivos = [], demais = [];\n  for (const x of xs) (x > 0 ? positivos : demais).push(x);\n  return «{ positivos, demais }»;\n}','separar([-1,0,2])',{positivos:[2],demais:[-1,0]},'O retorno reúne dois resultados sem perder a ordem de cada grupo.');
ret('Fatorial com base','Complete o retorno do caso-base da recursão.','function fatorial(n) {\n  if (n <= 1) return «1»;\n  return n * fatorial(n - 1);\n}','[fatorial(0),fatorial(5)]',[1,120],'O produto vazio e o fatorial de um valem um.');
ret('Soma recursiva','Propague o resultado da chamada recursiva.','function soma(xs) {\n  if (!xs.length) return 0;\n  return «xs[0] + soma(xs.slice(1))»;\n}','[soma([2,3,4]),soma([])]',[9,0],'A cabeça é somada ao retorno que processa a cauda.');
ret('MDC por retorno recursivo','Devolva a próxima etapa do algoritmo de Euclides.','function mdc(a,b) {\n  if (b === 0) return a;\n  return «mdc(b, a % b)»;\n}','[mdc(48,18),mdc(7,0)]',[6,7],'A recursão substitui os argumentos pelo divisor e pelo resto.');
ret('Composição de funções','Retorne o resultado de g aplicado ao retorno de f.','function compor(f,g) {\n  return x => { return «g(f(x))»; };\n}\nconst calcular = compor(x=>x+2,x=>x*3);','[calcular(1),calcular(0)]',[9,6],'A ordem solicitada é primeiro f, depois g.');
ret('Atualização imutável','Retorne novo objeto com saldo atualizado sem modificar o original.','function creditar(conta,valor) {\n  return «{ ...conta, saldo: conta.saldo + valor }»;\n}\nconst conta = {nome:"Ana",saldo:10};','[creditar(conta,5),conta.saldo]',[{nome:'Ana',saldo:15},10],'A propriedade saldo posterior ao spread substitui apenas o saldo da cópia.');
ret('Retorno com desestruturação','Devolva nome com valor padrão ao desestruturar o parâmetro.','function nome({ nome = "Anônimo" } = {}) {\n  return «nome»;\n}','[nome({nome:"Rui"}),nome()]',['Rui','Anônimo'],'O binding local nome já contém o valor padrão quando a propriedade falta.');
ret('Comparador para sort','Retorne a diferença que ordena preços de forma crescente.','function comparar(a,b) {\n  return «a.preco - b.preco»;\n}\nconst produtos = [{preco:8},{preco:2},{preco:5}];','produtos.sort(comparar).map(p=>p.preco)',[2,5,8],'Valor negativo coloca a antes de b.');
ret('Busca por caminho opcional','Retorne o CEP, ou desconhecido se o caminho estiver ausente.','function cep(pessoa) {\n  return «pessoa?.endereco?.cep ?? "desconhecido"»;\n}','[cep({endereco:{cep:"123"}}),cep(null)]',['123','desconhecido'],'Encadeamento opcional interrompe o acesso; ?? fornece o fallback.');
ret('Intervalo limitado','Retorne o valor limitado entre mínimo e máximo.','function limitar(n,min,max) {\n  return «Math.min(max, Math.max(min, n))¦Math.max(min, Math.min(max, n))»;\n}','[limitar(-2,0,10),limitar(8,0,10),limitar(20,0,10)]',[0,8,10],'Primeiro imponha um limite e depois o outro.');
ret('Normalização com fallback','Retorne o texto aparado, ou sem nome se o resultado ficar vazio.','function rotulo(texto) {\n  const limpo = texto.trim();\n  return «limpo || "sem nome"»;\n}','[rotulo("  "),rotulo(" A ")]',['sem nome','A'],'Aqui a string vazia deve deliberadamente ativar o fallback.');
ret('Índice da primeira falha','Retorne imediatamente o índice do primeiro valor negativo.','function falha(xs) {\n  for (let i=0;i<xs.length;i++) {\n    if (xs[i] < 0) return «i»;\n  }\n  return -1;\n}','[falha([1,-2,-3]),falha([0,1])]',[1,-1],'O índice e o valor do elemento são resultados diferentes.');
ret('Menor palavra com reduce','Devolva o acumulador escolhido a cada etapa.','function menor(xs) {\n  return xs.reduce((a,b) => {\n    return «a.length <= b.length ? a : b»;\n  });\n}','menor(["casa","sol","a"])','a','Use <= para preservar o primeiro item em empates.');
ret('Remover uma propriedade','Retorne o restante do objeto após extrair senha.','function publico(usuario) {\n  const { senha, ...restante } = usuario;\n  return «restante»;\n}','publico({nome:"Ana",senha:"segredo",ativo:true})',{nome:'Ana',ativo:true},'O rest do objeto contém somente as propriedades não extraídas.');
ret('Retorno de método encadeável','Devolva a própria instância para encadear chamadas.','class Contador {\n  n = 0;\n  somar(x) { this.n += x; return «this»; }\n}\nconst c = new Contador();','c.somar(2).somar(3).n',5,'this permite que a próxima chamada opere no mesmo objeto.');
ret('Validação de todos os itens','Use retorno antecipado para reprovar no primeiro item inválido.','function todosPositivos(xs) {\n  for (const x of xs) if (x <= 0) «return false»;\n  return true;\n}','[todosPositivos([1,2]),todosPositivos([1,0]),todosPositivos([])]',[true,false,true],'Uma lista vazia não contém contraexemplos à condição.');
ret('Retorno de predicado em filter','Retorne o teste de presença de e-mail.','const usuarios=[{email:"a@x"},{email:""},{email:"b@x"}];\nconst validos=usuarios.filter(u=>{\n  return «u.email.length > 0»;\n});','validos.length',2,'filter mantém os itens cujo callback devolve verdadeiro.');
ret('Restituir quociente e resto','Retorne os dois componentes da divisão inteira.','function dividirInteiro(a,b) {\n  return «{ quociente: Math.trunc(a / b), resto: a % b }»;\n}','dividirInteiro(17,5)',{quociente:3,resto:2},'trunc remove a fração; % fornece o resto.');
ret('Encontrar chave por valor','Retorne a primeira chave correspondente ou null.','function chaveDe(obj,valor) {\n  for (const [chave,v] of Object.entries(obj)) {\n    if (v === valor) return «chave»;\n  }\n  return null;\n}','[chaveDe({a:2,b:3},3),chaveDe({},3)]',['b',null],'A função retorna a chave da entrada, não seu valor.');
ret('Retornar uma função de descarte','Retorne um callback que altera o estado quando chamado.','let ativo=true;\nfunction assinatura() {\n  return () => { «ativo = false»; };\n}\nconst cancelar=assinatura();\nconst antes=ativo;\ncancelar();','[antes,ativo]',[true,false],'Criar a função não a executa; a mudança ocorre no cancelamento.');
ret('Soma até sentinela','Retorne o acumulado quando encontrar null.','function parcial(xs) {\n  let total=0;\n  for (const x of xs) {\n    if (x === null) return «total»;\n    total += x;\n  }\n  return total;\n}','[parcial([2,3,null,8]),parcial([])]',[5,0],'O retorno interrompe a leitura antes dos itens posteriores à sentinela.');
ret('Retorno com parâmetro padrão','Devolva a potência usando expoente dois por padrão.','function potencia(base,expoente=2) {\n  return «base ** expoente»;\n}','[potencia(3),potencia(2,3)]',[9,8],'O operador ** expressa exponenciação.');
ret('Preservar o zero de uma busca','Retorne o índice encontrado inclusive quando é zero.','function posicao(xs,x) {\n  const i=xs.indexOf(x);\n  return «i === -1 ? null : i»;\n}','[posicao([4,5],4),posicao([4,5],9)]',[0,null],'Zero não significa ausência; indexOf usa -1 para isso.');
ret('Retorno em múltiplas linhas','Complete o objeto já agrupado após return.','function resposta() {\n  return (\n    «{ ok: true, codigo: 200 }»\n  );\n}','resposta()',{ok:true,codigo:200},'Abrir o parêntese na linha de return evita a inserção automática de ponto e vírgula.');
ret('Diagnosticar return isolado','Retorne o tipo de valor devolvido pela função com quebra após return.','function exemplo() {\n  return\n  { valor: 3 };\n}\nfunction diagnostico() {\n  return «typeof exemplo()»;\n}','diagnostico()','undefined','A quebra de linha encerra return; o objeto seguinte não é retornado.');

group('return','hard');
ret('Busca binária recursiva','Propague a busca na metade direita quando o alvo for maior.','function busca(xs,alvo,inicio=0,fim=xs.length-1) {\n  if (inicio > fim) return -1;\n  const meio=Math.floor((inicio+fim)/2);\n  if (xs[meio] === alvo) return meio;\n  if (xs[meio] > alvo) return busca(xs,alvo,inicio,meio-1);\n  return «busca(xs, alvo, meio + 1, fim)»;\n}','[busca([1,3,5,7],7),busca([1,3],2),busca([],1)]',[3,-1,-1],'O intervalo direito começa após meio; devolva o resultado recursivo.');
ret('Altura de árvore','Retorne um mais a maior altura dos filhos.','function altura(no) {\n  if (!no) return 0;\n  return «1 + Math.max(altura(no.esq), altura(no.dir))»;\n}\nconst arvore={esq:{esq:{}},dir:{}};','[altura(arvore),altura(null)]',[3,0],'A base vazia tem altura zero; cada nó soma um nível.');
ret('Busca profunda em árvore','Retorne o resultado encontrado em um filho sem descartá-lo.','function encontrar(no,id) {\n  if (no.id === id) return no;\n  for (const filho of no.filhos || []) {\n    const achado=encontrar(filho,id);\n    if (achado) return «achado»;\n  }\n  return null;\n}\nconst raiz={id:1,filhos:[{id:2}]};','[encontrar(raiz,2),encontrar(raiz,9)]',[{id:2},null],'A descoberta precisa ser propagada por todos os níveis da pilha.');
ret('Achatar arrays recursivamente','Retorne a concatenação dos resultados recursivos.','function achatar(xs) {\n  return xs.flatMap(x=>{\n    if (Array.isArray(x)) return «achatar(x)»;\n    return [x];\n  });\n}','[achatar([1,[2,[3]]]),achatar([])]',[[1,2,3],[]],'flatMap achata um nível de cada array retornado pelo callback.');
ret('Memoização de Fibonacci','Retorne o valor memorizado ao detectar uma chamada repetida.','const memoria=new Map([[0,0],[1,1]]);\nfunction fib(n) {\n  if (memoria.has(n)) return «memoria.get(n)»;\n  const valor=fib(n-1)+fib(n-2);\n  memoria.set(n,valor);\n  return valor;\n}','[fib(10),fib(0),fib(10)]',[55,0,55],'A guarda de cache evita recomputar subproblemas e preserva zero.');
ret('Trampolim de retornos','Retorne uma continuação em vez de recursão imediata.','function soma(n,total=0) {\n  if (n === 0) return total;\n  return «() => soma(n - 1, total + n)»;\n}\nfunction executar(valor) {\n  while (typeof valor === "function") valor=valor();\n  return valor;\n}','[executar(soma(1000)),executar(soma(0))]',[500500,0],'Uma função adiada permite que o trampolim avance sem acumular chamadas recursivas.');
ret('Currying de três argumentos','Retorne a função que recebe o último operando.','function somar(a) {\n  return b => {\n    return «c => a + b + c»;\n  };\n}','[somar(1)(2)(3),somar(0)(0)(0)]',[6,0],'Cada chamada captura um argumento e devolve a próxima função.');
ret('Pipe com acumulador','Devolva a saída de cada função ao reduce.','function pipe(...funcoes) {\n  return inicial => funcoes.reduce((valor,fn)=>{\n    return «fn(valor)»;\n  },inicial);\n}','[pipe(x=>x+1,x=>x*2)(3),pipe()(8)]',[8,8],'O retorno de uma etapa vira entrada da seguinte; pipe vazio é identidade.');
ret('Memoização por argumentos','Retorne a computação armazenada com chave composta.','let chamadas=0;\nfunction memo(fn) {\n  const cache=new Map();\n  return (...args)=>{\n    const chave=JSON.stringify(args);\n    if (!cache.has(chave)) cache.set(chave,fn(...args));\n    return «cache.get(chave)»;\n  };\n}\nconst soma=memo((a,b)=>{chamadas++;return a+b;});\nconst valores=[soma(2,3),soma(2,3),soma(3,2)];','[valores,chamadas]',[[5,5,5],2],'A ordem dos argumentos compõe a chave e o retorno vem do cache.');
ret('Uma única execução','Retorne o primeiro resultado em chamadas posteriores.','function umaVez(fn) {\n  let feito=false,valor;\n  return ()=>{\n    if (!feito) { valor=fn(); feito=true; }\n    return «valor»;\n  };\n}\nlet n=0;\nconst proximo=umaVez(()=>++n);','[proximo(),proximo(),n]',[1,1,1],'A flag separada é necessária porque o resultado pode ser falsy.');
ret('Retorno final de generator','Complete o valor de encerramento do iterador.','function* passos() {\n  yield 1;\n  return «9»;\n}\nconst it=passos();','[it.next(),it.next(),it.next().done]',[{value:1,done:false},{value:9,done:true},true],'O valor de return aparece no next que encerra, com done true.');
ret('Propagar return com yield estrela','Capture o retorno do gerador delegado.','function* filho() { yield "a"; return 7; }\nfunction* pai() {\n  const final=yield* filho();\n  return «final * 2»;\n}\nconst it=pai();','[it.next(),it.next()]',[{value:'a',done:false},{value:14,done:true}],'yield* avalia para o valor de retorno do gerador delegado.');
ret('Retorno em finally','Complete a observação: o retorno de finally substitui o de try.','function escolher() {\n  try { return "try"; }\n  finally { return «"finally"»; }\n}','escolher()','finally','Evite return em finally em código real quando ele puder esconder o resultado anterior.');
ret('Objeto alterado após return','Retorne o objeto cuja propriedade será alterada em finally.','function objeto() {\n  const x={valor:1};\n  try { return «x»; }\n  finally { x.valor=2; }\n}','objeto()',{valor:2},'O retorno preserva a referência; finally ainda pode mutar o objeto.');
ret('Primitivo capturado antes de finally','Retorne o número antes da alteração da variável local.','function numero() {\n  let x=1;\n  try { return «x»; }\n  finally { x=2; }\n}','numero()',1,'O valor primitivo de retorno já foi avaliado quando finally muda a variável.');
ret('Cópia profunda recursiva','Retorne a reconstrução de um objeto JSON sem compartilhar filhos.','function copiar(x) {\n  if (x === null || typeof x !== "object") return x;\n  if (Array.isArray(x)) return x.map(copiar);\n  return «Object.fromEntries(Object.entries(x).map(([k,v]) => [k,copiar(v)]))»;\n}\nconst a={lista:[{x:1}]};\nconst b=copiar(a);\nb.lista[0].x=9;','[a.lista[0].x,b.lista[0].x]',[1,9],'A reconstrução recursiva serve para esta entrada JSON, sem ciclos.');
ret('Caminho até o alvo','Retorne o caminho encontrado na busca em profundidade.','function caminho(no,id,trilha=[]) {\n  const atual=[...trilha,no.id];\n  if (no.id===id) return atual;\n  for (const filho of no.filhos||[]) {\n    const r=caminho(filho,id,atual);\n    if (r) return «r»;\n  }\n  return null;\n}\nconst raiz={id:"a",filhos:[{id:"b",filhos:[{id:"c"}]}]};','[caminho(raiz,"c"),caminho(raiz,"z")]',[['a','b','c'],null],'Cada nível estende a trilha e propaga o primeiro resultado não nulo.');
ret('Índice de inserção','Retorne o limite inferior após a busca binária iterativa.','function inserirEm(xs,x) {\n  let l=0,r=xs.length;\n  while(l<r) { const m=(l+r)>>1; if(xs[m]<x) l=m+1; else r=m; }\n  return «l¦r»;\n}','[inserirEm([1,3,3,8],3),inserirEm([],1),inserirEm([1],2)]',[1,0,1],'Ao terminar, l e r coincidem na primeira posição não menor que x.');
ret('Retornar do getter','Devolva a propriedade derivada sem armazená-la.','class Caixa {\n  constructor(w,h) { this.w=w; this.h=h; }\n  get area() { return «this.w * this.h¦this.h * this.w»; }\n}\nconst c=new Caixa(2,3);\nconst antes=c.area;\nc.w=4;','[antes,c.area]',[6,12],'O getter recalcula o valor em cada leitura.');
ret('Comparação lexicográfica','Retorne o desempate por nome quando a prioridade coincide.','function comparar(a,b) {\n  if (a.p !== b.p) return a.p-b.p;\n  return «a.nome < b.nome ? -1 : a.nome > b.nome ? 1 : 0»;\n}\nconst xs=[{p:2,nome:"a"},{p:1,nome:"c"},{p:1,nome:"b"}];','xs.sort(comparar).map(x=>x.nome)',['b','c','a'],'O segundo critério só é usado em empate no primeiro.');
ret('Factory com estado privado','Retorne uma API que fecha sobre o saldo privado.','function carteira() {\n  let saldo=0;\n  return «{ depositar: n => saldo += n, consultar: () => saldo }»;\n}\nconst c=carteira();\nc.depositar(5);\nc.depositar(2);','[c.consultar(),"saldo" in c]',[7,false],'A API retornada expõe operações, sem expor a variável saldo.');
ret('Resultado imutável','Retorne um objeto congelado com a resposta calculada.','function calcular(a,b) {\n  return «Object.freeze({ soma: a + b })»;\n}\nconst r=calcular(2,4);','[r.soma,Object.isFrozen(r)]',[6,true],'Object.freeze devolve o próprio objeto depois de congelá-lo.');
ret('Propagar rejeição de validador','Retorne o primeiro resultado de falha em uma cadeia síncrona.','function validar(x,regras) {\n  for(const regra of regras) { const r=regra(x); if(!r.ok) return «r»; }\n  return {ok:true};\n}\nconst regras=[x=>({ok:x>0,motivo:"positivo"}),x=>({ok:x<10,motivo:"limite"})];','[validar(-1,regras),validar(5,regras)]',[{ok:false,motivo:'positivo'},{ok:true}],'O primeiro resultado negativo é devolvido sem executar as regras restantes.');
ret('Resolver caminho pontuado','Retorne undefined assim que um segmento não existir.','function ler(obj,caminho) {\n  let atual=obj;\n  for(const parte of caminho.split(".")) {\n    if(atual == null) «return undefined»;\n    atual=atual[parte];\n  }\n  return atual;\n}','[ler({a:{b:2}},"a.b"),typeof ler({},"a.b")]',[2,'undefined'],'A guarda encerra a função antes do próximo acesso inválido.');
ret('Backtracking para soma','Retorne true ao encontrar uma combinação que atinge o alvo.','function existe(xs,alvo,i=0) {\n  if(alvo===0) return true;\n  if(i===xs.length) return false;\n  return «existe(xs, alvo - xs[i], i + 1) || existe(xs, alvo, i + 1)»;\n}','[existe([2,4,7],6),existe([2,4],3)]',[true,false],'As duas escolhas são incluir ou ignorar o item atual.');
ret('Árvore de expressão','Retorne a avaliação recursiva dos operandos da multiplicação.','function avaliar(no) {\n  if(typeof no === "number") return no;\n  if(no.op === "+") return avaliar(no.a)+avaliar(no.b);\n  return «avaliar(no.a) * avaliar(no.b)»;\n}','avaliar({op:"*",a:{op:"+",a:2,b:3},b:4})',20,'Cada retorno transforma uma subárvore em um valor numérico.');
ret('Retorno de construtor','Devolva outro objeto explicitamente para substituir a instância criada.','function Pessoa() {\n  this.nome="interno";\n  return «{ nome: "externo" }»;\n}\nconst p=new Pessoa();','[p.nome,p instanceof Pessoa]',['externo',false],'Um objeto retornado por um construtor substitui o this criado por new.');
ret('Retorno primitivo de construtor','Devolva um primitivo e observe que new mantém a instância.','function Produto() {\n  this.preco=10;\n  return «99»;\n}\nconst p=new Produto();','[p.preco,p instanceof Produto]',[10,true],'O retorno primitivo de um construtor comum é ignorado por new.');
ret('Retorno antecipado em grafo cíclico','Interrompa a visita a nós já vistos.','function visitar(no,vistos=new Set()) {\n  if(vistos.has(no)) «return 0»;\n  vistos.add(no);\n  return 1 + no.proximos.reduce((s,n)=>s+visitar(n,vistos),0);\n}\nconst a={proximos:[]},b={proximos:[a]};\na.proximos.push(b);','visitar(a)',2,'A guarda evita recursão infinita e contagem dupla.');
ret('Retorno de acumulador em reduceRight','Retorne a aplicação que compõe funções da direita para a esquerda.','function comporDireita(...fns) {\n  return x=>fns.reduceRight((v,fn)=>{return «fn(v)»;},x);\n}','[comporDireita(x=>x*2,x=>x+3)(4),comporDireita()(4)]',[14,4],'reduceRight começa pela última função fornecida.');
function tc(title,goal,source,expected,hint){add(title,goal,source+'\nconsole.log(JSON.stringify(resultado));',expected,hint);}
group('try-catch','easy');
tc('Capturar JSON quebrado','Capture a falha de JSON.parse e use null como fallback.','let resultado;\ntry { resultado=JSON.parse("{quebrado}"); }\n«catch» (erro) { resultado=null; }',null,'catch recebe a exceção lançada no bloco try.');
tc('Ler mensagem do erro','Extraia a mensagem do objeto Error capturado.','let resultado;\ntry { throw new Error("Arquivo ausente"); }\ncatch (erro) { resultado=«erro.message»; }','Arquivo ausente','message contém a mensagem; String(erro) também incluiria o nome do erro.');
tc('Lançar erro de estoque','Lance uma exceção quando não houver unidades.','let resultado;\ntry {\n  const estoque=0;\n  if(estoque===0) «throw new Error("Sem estoque")»;\n  resultado="vendido";\n} catch(erro) { resultado=erro.message; }','Sem estoque','throw interrompe o fluxo normal e transfere o controle ao catch.');
tc('Caminho sem exceção','Complete o bloco protegido e observe que catch não roda.','let resultado;\n«try» { resultado=JSON.parse("[1,2]").length; }\ncatch { resultado=-1; }',2,'try também pode terminar normalmente.');
tc('Finalizar depois de sucesso','Acrescente a etapa de limpeza após um try bem-sucedido.','const resultado=[];\ntry { resultado.push("ok"); }\n«finally» { resultado.push("limpeza"); }',['ok','limpeza'],'finally executa após o caminho normal.');
tc('Finalizar depois de falha','Faça a limpeza também depois de capturar um erro.','const resultado=[];\ntry { throw new Error("falha"); }\ncatch { resultado.push("erro"); }\n«finally» { resultado.push("limpeza"); }',['erro','limpeza'],'finally também executa depois do catch.');
tc('Catch sem variável','Capture o erro sem precisar consultar o objeto lançado.','let resultado;\ntry { JSON.parse("?"); }\n«catch» { resultado="inválido"; }','inválido','A variável entre parênteses é opcional quando você não precisa do erro.');
tc('URI malformada','Capture a falha de decodeURIComponent.','let resultado;\ntry { resultado=decodeURIComponent("%ZZ"); }\ncatch(erro) { resultado=«erro.name»; }','URIError','name identifica a categoria do erro.');
tc('Comprimento inválido de array','Capture o tipo de erro ao criar um array de tamanho negativo.','let resultado;\ntry { new Array(-1); }\ncatch(erro) { resultado=«erro.name»; }','RangeError','Um comprimento de array fora do intervalo permitido lança RangeError.');
tc('Método inexistente','Capture a tentativa de chamar um número como função.','let resultado;\ntry { const n=3; n(); }\ncatch(erro) { resultado=erro instanceof «TypeError»; }',true,'Chamar um valor não executável produz TypeError.');
tc('Exceção textual','Capture uma string lançada diretamente, sem presumir Error.','let resultado;\ntry { throw "texto"; }\ncatch(erro) { resultado=«erro»; }','texto','JavaScript permite lançar outros valores; neste caso o capturado já é a string.');
tc('Exceção numérica','Devolva o número recebido pelo catch.','let resultado;\ntry { «throw 404»; }\ncatch(codigo) { resultado=codigo; }',404,'O valor lançado é entregue diretamente ao catch.');
tc('Falha não continua no try','Capture a exceção antes da segunda marca.','const resultado=[];\ntry {\n  resultado.push("antes");\n  «throw new Error("parar")»;\n  resultado.push("depois");\n} catch { resultado.push("capturado"); }',['antes','capturado'],'As instruções após throw não são executadas naquele bloco.');
tc('Continuar depois do catch','Complete o catch e observe a retomada após ele.','const resultado=[];\ntry { throw new Error("x"); }\n«catch» { resultado.push("recuperado"); }\nresultado.push("fim");',['recuperado','fim'],'Depois de tratar o erro, o programa continua fora do bloco.');
tc('Converter com validação','Lance erro explicitamente quando Number produzir NaN.','let resultado;\ntry {\n  const n=Number("abc");\n  if(Number.isNaN(n)) «throw new Error("Não numérico")»;\n  resultado=n;\n} catch(erro) { resultado=erro.message; }','Não numérico','Number de uma string inválida produz NaN; isso não lança erro por si só.');
tc('Divisão por zero explícita','Rejeite divisor zero antes da operação.','let resultado;\ntry {\n  const divisor=0;\n  if(divisor===0) «throw new RangeError("Divisor zero")»;\n  resultado=10/divisor;\n} catch(erro) { resultado=erro.message; }','Divisor zero','Dividir números por zero produz Infinity; você precisa lançar a exceção desejada.');
tc('Acesso em null','Capture o erro de acessar uma propriedade de null.','let resultado;\ntry { const usuario=null; resultado=usuario.nome; }\ncatch(erro) { resultado=erro instanceof «TypeError»; }',true,'O acesso direto em null lança TypeError.');
tc('BigInt inválido','Capture SyntaxError ao converter texto decimal fracionário para BigInt.','let resultado;\ntry { BigInt("1.5"); }\ncatch(erro) { resultado=erro instanceof «SyntaxError»; }',true,'O construtor BigInt não aceita uma string fracionária.');
tc('Objeto circular','Capture a falha de serialização de referência circular.','let resultado;\nconst obj={}; obj.eu=obj;\ntry { JSON.stringify(obj); }\ncatch(erro) { resultado=erro instanceof «TypeError»; }',true,'JSON.stringify não suporta ciclos por padrão.');
tc('Validar tamanho de nome','Lance erro quando o nome ficar vazio após trim.','let resultado;\ntry {\n  const nome="   ".trim();\n  if(!nome) «throw new Error("Nome obrigatório")»;\n  resultado=nome;\n} catch(erro) { resultado=erro.message; }','Nome obrigatório','A validação de regra de negócio precisa ser explícita.');
tc('Código de erro próprio','Leia a propriedade code adicionada ao erro.','let resultado;\ntry {\n  const erro=new Error("Ausente"); erro.code="ENOENT";\n  throw erro;\n} catch(erro) { resultado=«erro.code»; }','ENOENT','Erros podem carregar propriedades adicionais como code.');
tc('Capturar função chamada','Proteja a chamada de uma função que lança internamente.','function abrir() { throw new Error("Porta fechada"); }\nlet resultado;\ntry { abrir(); }\ncatch(erro) { resultado=«erro.message»; }','Porta fechada','Exceções síncronas propagam até o catch mais próximo na pilha.');
tc('Limpeza sem catch','Complete a limpeza de um try que não lança exceção.','let aberto=true;\ntry { /* uso do recurso */ }\nfinally { aberto=«false»; }\nconst resultado=aberto;',false,'É válido usar try/finally sem catch.');
tc('Gerar erro de intervalo','Use a classe apropriada para uma quantidade negativa.','let resultado;\ntry { throw new «RangeError»("Quantidade negativa"); }\ncatch(erro) { resultado=erro.name; }','RangeError','RangeError comunica que o valor está fora do intervalo esperado.');
tc('Gerar erro de tipo','Use a classe apropriada para um argumento com tipo incorreto.','let resultado;\ntry { throw new «TypeError»("Esperava texto"); }\ncatch(erro) { resultado=erro.name; }','TypeError','TypeError comunica incompatibilidade de tipo.');
tc('Preservar erro original','Atribua o próprio objeto capturado ao resultado intermediário.','const original=new Error("origem");\nlet capturado;\ntry { throw original; }\ncatch(erro) { capturado=«erro»; }\nconst resultado=capturado===original;',true,'Capturar não clona o objeto lançado.');
tc('Fallback de configuração','Use objeto padrão ao falhar a leitura de JSON.','let resultado;\ntry { resultado=JSON.parse("inválido"); }\ncatch { resultado=«{ tema: "escuro" }»; }',{tema:'escuro'},'O fallback é um objeto utilizável pelo restante da aplicação.');
tc('Marcar recurso como fechado','Feche o recurso no finally mesmo que haja erro.','const recurso={aberto:true};\ntry { throw new Error("x"); }\ncatch {}\nfinally { recurso.aberto=«false»; }\nconst resultado=recurso.aberto;',false,'A limpeza pertence ao finally porque ele cobre os dois caminhos.');
tc('Validação de inteiro','Rejeite valores fracionários com uma exceção explícita.','let resultado;\ntry {\n  const n=2.5;\n  if(!Number.isInteger(n)) «throw new Error("Inteiro obrigatório")»;\n  resultado=n;\n} catch(erro) { resultado=erro.message; }','Inteiro obrigatório','Number.isInteger permite decidir quando lançar a exceção.');
tc('Operação bem-sucedida com finally','Preserve o resultado enquanto registra uma limpeza separada.','let valor,limpo=false;\ntry { valor=6*7; }\nfinally { limpo=«true»; }\nconst resultado=[valor,limpo];',[42,true],'Limpar um recurso não exige substituir o resultado da operação.');

group('try-catch','medium');
tc('Tratar apenas SyntaxError','Use fallback para JSON inválido e propague outros erros.','function ler(texto) {\n  try { return JSON.parse(texto); }\n  catch(erro) {\n    if(erro instanceof SyntaxError) return null;\n    «throw erro»;\n  }\n}\nconst resultado=[ler("?"),ler("0")];',[null,0],'Relançar o mesmo erro preserva seu tipo e contexto.');
tc('Relançamento até camada externa','Propague o erro interno para o catch externo.','let resultado;\ntry {\n  try { throw new Error("origem"); }\n  catch(erro) { «throw erro»; }\n} catch(erro) { resultado=erro.message; }','origem','Um catch não precisa resolver a falha; pode delegá-la.');
tc('Traduzir erro mantendo causa','Crie erro de domínio mantendo o erro original em cause.','let resultado;\ntry {\n  try { JSON.parse("?"); }\n  catch(erro) { throw new Error("Config inválida", { cause: «erro» }); }\n} catch(erro) { resultado=[erro.message,erro.cause.name]; }',['Config inválida','SyntaxError'],'cause conserva a origem enquanto a mensagem explica o contexto.');
tc('Recuperação por item','Continue processando a lista após um item inválido.','const resultado=[];\nfor(const texto of ["1","?","2"]) {\n  try { resultado.push(JSON.parse(texto)); }\n  «catch» { resultado.push(null); }\n}',[1,null,2],'O try/catch dentro do laço isola a falha de cada item.');
tc('Interromper lote inteiro','Capture fora do laço para parar no primeiro erro.','const resultado=[];\ntry {\n  for(const texto of ["1","?","2"]) resultado.push(JSON.parse(texto));\n} «catch» { resultado.push("interrompido"); }',[1,'interrompido'],'A exceção abandona o laço até alcançar o catch externo.');
tc('Rollback de saldo','Restaure o valor anterior se uma validação falhar.','let saldo=100;\nconst anterior=saldo;\ntry {\n  saldo-=120;\n  if(saldo<0) throw new Error("Saldo insuficiente");\n} catch { saldo=«anterior»; }\nconst resultado=saldo;',100,'Guardar o estado anterior permite desfazer a mutação local.');
tc('Capturar erro de getter','Proteja também a leitura de uma propriedade com getter.','const obj={ get valor(){throw new Error("Leitura negada");} };\nlet resultado;\ntry { resultado=obj.valor; }\ncatch(erro) { resultado=«erro.message»; }','Leitura negada','Uma leitura de propriedade pode executar código e lançar.');
tc('Capturar erro de setter','Trate a rejeição de uma atribuição validada.','const obj={ set idade(n){if(n<0)throw new RangeError("Idade negativa");} };\nlet resultado;\ntry { obj.idade=-1; }\ncatch(erro) { resultado=«erro.name»; }','RangeError','O setter executa durante a atribuição e pode falhar.');
tc('Tratamento por código','Diferencie arquivo ausente de erro inesperado.','function abrir() { const e=new Error("ausente");e.code="ENOENT";throw e; }\nlet resultado;\ntry { abrir(); }\ncatch(erro) {\n  if(«erro.code === "ENOENT"») resultado="criar arquivo";\n  else throw erro;\n}','criar arquivo','Compare o código estável em vez de depender do texto da mensagem.');
tc('Mensagem de valor desconhecido','Normalize erros que podem ser Error ou string.','function mensagem(valor) {\n  try { throw valor; }\n  catch(erro) { return erro instanceof Error ? erro.message : «String(erro)»; }\n}\nconst resultado=[mensagem(new Error("a")),mensagem("b"),mensagem(null)];',['a','b','null'],'O catch não garante que o valor capturado seja instância de Error.');
tc('Retornar fallback de função','Devolva valor padrão ao capturar a conversão inválida.','function converter(texto) {\n  try { return BigInt(texto).toString(); }\n  catch { «return "0"»; }\n}\nconst resultado=[converter("12"),converter("x")];',['12','0'],'O retorno do catch define uma política explícita de recuperação.');
tc('Erro no catch','Capture externamente uma nova exceção lançada no tratamento.','let resultado;\ntry {\n  try { throw new Error("primeiro"); }\n  catch { «throw new Error("segundo")»; }\n} catch(erro) { resultado=erro.message; }','segundo','O catch associado não captura erros produzidos dentro dele próprio.');
tc('Erro na limpeza','Observe a exceção lançada pelo finally após um sucesso.','let resultado;\ntry {\n  try { /* sucesso */ }\n  finally { «throw new Error("fechamento")»; }\n} catch(erro) { resultado=erro.message; }','fechamento','Uma falha de limpeza também se propaga ao chamador.');
tc('Ordem de blocos aninhados','Complete a limpeza interna antes do tratamento externo.','const resultado=[];\ntry {\n  try { throw new Error("x"); }\n  «finally» { resultado.push("interno"); }\n} catch { resultado.push("externo"); }',['interno','externo'],'finally roda durante o desenrolar da pilha antes do catch externo.');
tc('Limpeza antes de retornar fallback','Finalize o recurso mesmo ao retornar dentro de catch.','const marcas=[];\nfunction executar() {\n  try { throw new Error("x"); }\n  catch { return "fallback"; }\n  finally { marcas.push(«"fechado"»); }\n}\nconst resultado=[executar(),marcas];',['fallback',['fechado']],'Um return no catch não pula o finally.');
tc('Validação estrutural após parse','Lance TypeError se o JSON válido não tiver a lista esperada.','function ler(texto) {\n  try {\n    const x=JSON.parse(texto);\n    if(!Array.isArray(x.itens)) «throw new TypeError("itens deve ser array")»;\n    return x.itens.length;\n  } catch(e) { return e.name; }\n}\nconst resultado=[ler("{}"),ler(JSON.stringify({itens:[1]}))];',['TypeError',1],'JSON sintaticamente válido não garante o formato exigido pela aplicação.');
tc('Erro de domínio customizado','Complete a herança de uma classe de erro.','class SaldoError extends «Error» {}\nlet resultado;\ntry { throw new SaldoError("Sem saldo"); }\ncatch(e) { resultado=[e instanceof SaldoError,e instanceof Error]; }',[true,true],'Uma subclasse de Error permite identificar falhas de domínio.');
tc('Nome da subclasse','Defina o nome customizado após chamar super.','class ValidacaoError extends Error {\n  constructor(m) { super(m); this.name=«"ValidacaoError"»; }\n}\nlet resultado;\ntry { throw new ValidacaoError("campo"); }\ncatch(e) { resultado=[e.name,e.message]; }',['ValidacaoError','campo'],'A herança sozinha não muda automaticamente a propriedade name de Error.');
tc('Falha em callback síncrono','Capture um erro lançado por map durante a chamada.','let resultado;\ntry {\n  [1,-1,2].map(n=>{if(n<0) throw new Error("negativo");return n;});\n} catch(e) { resultado=«e.message»; }','negativo','Callbacks síncronos de map executam dentro da pilha protegida.');
tc('Falha no comparador','Trate um comparador que rejeita um item inválido.','let resultado;\ntry {\n  [2,null,1].sort((a,b)=>{if(a===null||b===null)throw new TypeError("nulo");return a-b;});\n} catch(e) { resultado=«e.name»; }','TypeError','Exceções síncronas do comparador propagam para fora de sort.');
tc('Tentativas síncronas limitadas','Relance apenas na última tentativa permitida.','let chamadas=0,resultado;\nfunction operar(){if(++chamadas<3)throw new Error("temporário");return "ok";}\nfor(let tentativa=1;tentativa<=3;tentativa++){\n  try { resultado=operar();break; }\n  catch(e){if(tentativa===3) «throw e»;}\n}\nresultado=[resultado,chamadas];',['ok',3],'Cada falha é tolerada até o limite; a última precisa ser propagada.');
tc('Coletar erros sem interromper','Armazene mensagens de todas as falhas de validação.','const resultado=[];\nfor(const n of [-1,2,-3]) {\n  try { if(n<0)throw new Error("negativo:"+n); }\n  catch(e) { resultado.push(«e.message»); }\n}',['negativo:-1','negativo:-3'],'A coleta acontece no catch por item, sem lançar novamente.');
tc('Não confundir NaN com exceção','Complete o indicador para o caminho que realmente executou.','let resultado;\ntry { Number("abc"); resultado=«"sem exceção"»; }\ncatch { resultado="erro"; }','sem exceção','NaN é um valor numérico especial, não uma exceção.');
tc('Data inválida ao serializar','Capture a falha de toISOString em uma data inválida.','let resultado;\ntry { new Date("inválida").toISOString(); }\ncatch(e) { resultado=«e.name»; }','RangeError','Criar a data inválida é permitido; toISOString é que lança.');
tc('Mistura de BigInt e Number','Capture a incompatibilidade aritmética.','let resultado;\ntry { resultado=1n+2; }\ncatch(e) { resultado=e instanceof «TypeError»; }',true,'A soma não mistura BigInt e Number implicitamente.');
tc('Congelamento em modo estrito','Capture tentativa de alterar objeto congelado em modo estrito.','function executar(){\n  "use strict";\n  const obj=Object.freeze({x:1});\n  try { obj.x=2; }\n  catch(e) { return «e.name»; }\n}\nconst resultado=executar();','TypeError','Em modo estrito, a escrita proibida lança em vez de falhar silenciosamente.');
tc('Fallback condicional de leitura','Trate ausência, mas não silencie falta de permissão.','function ler(codigo){\n  try { const e=new Error(codigo);e.code=codigo;throw e; }\n  catch(e){if(e.code==="ENOENT")return "vazio";«throw e»;}\n}\nlet negado;\ntry{ler("EACCES");}catch(e){negado=e.code;}\nconst resultado=[ler("ENOENT"),negado];',['vazio','EACCES'],'Somente o erro previsto recebe fallback.');
tc('Finally após break','Execute a limpeza mesmo quando o laço termina por break.','const resultado=[];\nfor(let i=0;i<3;i++){\n  try { resultado.push(i);break; }\n  «finally» { resultado.push("fim"); }\n}',[0,'fim'],'break também atravessa o finally antes de sair do laço.');
tc('Finally após continue','Registre a limpeza antes de cada próxima iteração.','const resultado=[];\nfor(let i=0;i<2;i++){\n  try { if(i===0)continue;resultado.push("uso"); }\n  «finally» { resultado.push("limpar"+i); }\n}',['limpar0','uso','limpar1'],'continue não impede a execução do finally.');
tc('Escopo do erro capturado','Copie a mensagem para uma variável fora do catch.','let mensagem;\ntry { throw new Error("falha"); }\ncatch(erro) { mensagem=«erro.message»; }\nconst resultado=mensagem;','falha','A variável erro é local ao catch; copie o dado necessário para fora.');

group('try-catch','hard');
tc('Agregar falhas de validação','Lance AggregateError contendo todos os erros coletados.','let resultado;\ntry {\n  const erros=[new Error("nome"),new Error("idade")];\n  throw new «AggregateError»(erros,"Cadastro inválido");\n} catch(e) { resultado=[e.message,e.errors.map(x=>x.message)]; }',['Cadastro inválido',['nome','idade']],'AggregateError preserva a coleção na propriedade errors.');
tc('Operação e limpeza falham','Preserve ambas as falhas em vez de deixar a limpeza esconder a original.','let resultado;\ntry {\n  let original;\n  try { throw new Error("operação"); } catch(e){original=e;}\n  try { throw new Error("limpeza"); }\n  catch(e) { throw new AggregateError(«[original, e]»,"dupla falha"); }\n} catch(e){resultado=e.errors.map(x=>x.message);}',['operação','limpeza'],'A agregação conserva as duas causas em ordem.');
tc('Percorrer cadeia de causas','Colete as mensagens seguindo cause até o fim.','const raiz=new Error("disco");\nconst topo=new Error("serviço",{cause:new Error("arquivo",{cause:raiz})});\nconst resultado=[];\ntry{throw topo;}catch(e){\n  for(let atual=e;atual;atual=«atual.cause») resultado.push(atual.message);\n}',['serviço','arquivo','disco'],'Cada cause aponta para o contexto original de uma camada anterior.');
tc('Evitar ciclo na cadeia de erros','Interrompa a leitura de causas quando o objeto já foi visto.','const a=new Error("a"),b=new Error("b");a.cause=b;b.cause=a;\nconst resultado=[],vistos=new Set();\ntry{throw a;}catch(e){\n  let atual=e;\n  while(atual&&!vistos.has(atual)){\n    resultado.push(atual.message);vistos.add(atual);atual=«atual.cause»;\n  }\n}',['a','b'],'O conjunto usa identidade dos objetos para impedir um ciclo infinito.');
tc('Fechar recursos em ordem inversa','Desfaça a aquisição parcial do último recurso para o primeiro.','const abertos=[],resultado=[];\ntry {\n  abertos.push("A","B");throw new Error("C falhou");\n} catch {}\nfinally { while(abertos.length) resultado.push(«abertos.pop()»); }',['B','A'],'Recursos dependentes costumam ser liberados na ordem inversa da aquisição.');
tc('Compensar etapas concluídas','Execute somente as compensações das etapas que chegaram a concluir.','let saldo=100,estoque=5;\nconst desfazer=[];\ntry {\n  saldo-=20;desfazer.push(()=>saldo+=20);\n  estoque--;desfazer.push(()=>estoque++);\n  throw new Error("entrega falhou");\n} catch { while(desfazer.length) «desfazer.pop()()»; }\nconst resultado=[saldo,estoque];',[100,5],'O pop retorna a função de compensação, que precisa ser chamada.');
tc('Restaurar contexto temporário','Restaure a configuração anterior mesmo com exceção.','let idioma="pt";\nfunction comIdioma(novo,fn){\n  const anterior=idioma;idioma=novo;\n  try{return fn();}\n  finally{idioma=«anterior»;}\n}\nlet visto;\ntry{comIdioma("en",()=>{visto=idioma;throw new Error("x");});}catch{}\nconst resultado=[visto,idioma];',['en','pt'],'O finally restaura o contexto que existia antes da operação.');
tc('Retentativa seletiva por código','Repita apenas erros temporários, rejeitando os permanentes.','let chamadas=0,resultado;\nfunction operar(){const e=new Error("negado");e.code="EACCES";throw e;}\ntry{\n  for(let i=0;i<3;i++){\n    try{chamadas++;operar();break;}\n    catch(e){if(e.code!=="EAGAIN"||i===2) «throw e»;}\n  }\n}catch(e){resultado=[e.code,chamadas];}',['EACCES',1],'Falhas permanentes devem sair imediatamente, sem consumir todas as tentativas.');
tc('Subclasse com campo específico','Preserve o caminho do campo que falhou na validação.','class CampoError extends Error{\n  constructor(campo){super("Inválido");this.campo=«campo»;}\n}\nlet resultado;\ntry{throw new CampoError("endereco.cep");}\ncatch(e){resultado={campo:e.campo,mensagem:e.message};}',{campo:'endereco.cep',mensagem:'Inválido'},'O erro de domínio inclui informação estruturada para orientar a correção.');
tc('Fronteira de erro em plugin','Converta a exceção de um plugin em resultado, sem interromper os demais.','function executar(fn){\n  try{return {ok:true,valor:fn()};}\n  catch(e){return «{ ok: false, erro: e.message }»;}\n}\nconst resultado=[executar(()=>2),executar(()=>{throw new Error("plugin");}),executar(()=>3)];',[{ok:true,valor:2},{ok:false,erro:'plugin'},{ok:true,valor:3}],'A fronteira converte uma falha local em um contrato de resultado explícito.');
tc('Transação em cópia temporária','Publique a cópia apenas se todas as validações passarem.','let estado={saldo:10};\ntry{\n  const rascunho={...estado};rascunho.saldo-=20;\n  if(rascunho.saldo<0)throw new Error("saldo");\n  estado=«rascunho»;\n}catch{}\nconst resultado=estado;', {saldo:10},'A atribuição de commit fica depois da validação; falhar mantém o estado original.');
tc('Exceção na obtenção do iterador','Capture erro que ocorre antes da primeira iteração.','const fonte={ [Symbol.iterator](){throw new Error("sem iterador");} };\nlet resultado;\ntry{for(const x of fonte){void x;}}\ncatch(e){resultado=«e.message»;}','sem iterador','for…of pode falhar já ao solicitar o iterador.');
tc('Encerramento automático do iterador','Complete o método de limpeza chamado quando o corpo do laço lança.','let fechado=false;\nconst fonte={ [Symbol.iterator](){return {next:()=>({value:1,done:false}),return(){fechado=«true»;return {done:true};}};} };\ntry{for(const x of fonte){throw new Error("corpo");}}catch{}\nconst resultado=fechado;',true,'Uma saída abrupta do corpo de for…of tenta fechar o iterador com return.');
tc('Generator recebe throw','Capture o erro injetado pelo consumidor do gerador.','function* fluxo(){\n  try{yield "pronto";}\n  catch(e){yield «e.message»;}\n}\nconst it=fluxo();\nit.next();\nconst resultado=it.throw(new Error("cancelado")).value;','cancelado','it.throw lança no ponto em que o gerador estava suspenso.');
tc('Limpeza ao fechar generator','Registre a limpeza quando o consumidor chama return.','const marcas=[];\nfunction* fluxo(){try{yield 1;yield 2;}finally{marcas.push(«"fechado"»);}}\nconst it=fluxo();it.next();it.return();\nconst resultado=marcas;',['fechado'],'O encerramento solicitado ao gerador executa seu finally.');
tc('Exceção não Error com mensagem','Normalize um objeto arbitrário sem usar instanceof como único caminho.','function mensagem(e){\n  if(e && typeof e.message==="string")return e.message;\n  return String(e);\n}\nlet resultado;\ntry{throw {message:"externo"};}\ncatch(e){resultado=«mensagem(e)»;}','externo','Objetos de bibliotecas ou de outros contextos podem transportar message sem herdar Error.');
tc('Não perder stack no relançamento','Preserve a identidade do erro ao propagar.','const original=new Error("origem");\nlet resultado;\ntry{\n  try{throw original;}\n  catch(e){«throw e»;}\n}catch(e){resultado=e===original;}',true,'Criar outro Error sem causa descartaria a identidade do original.');
tc('Limpeza idempotente','Evite fechar o recurso duas vezes entre catch e finally.','let fechado=false,fechamentos=0;\nfunction fechar(){if(fechado)return;fechado=true;fechamentos++;}\ntry{throw new Error("x");}\ncatch{fechar();}\nfinally{«fechar()»;}\nconst resultado=fechamentos;',1,'A função de limpeza guarda seu estado para tolerar chamadas repetidas.');
tc('Escopo de rollback aninhado','Restaure somente a alteração da etapa interna que falhou.','let saldo=100;\nsaldo-=10;\nconst checkpoint=saldo;\ntry{saldo-=200;throw new Error("etapa");}\ncatch{saldo=«checkpoint»;}\nconst resultado=saldo;',90,'O checkpoint interno preserva a etapa anterior já concluída.');
tc('Getter da mensagem também falha','Use proteção aninhada ao normalizar um erro hostil.','const estranho={get message(){throw new Error("getter");}};\nlet resultado;\ntry{throw estranho;}catch(e){\n  try{resultado=e.message;}\n  «catch»{resultado="erro sem mensagem";}\n}','erro sem mensagem','Até ler propriedades de um valor capturado pode executar código.');
tc('Preservar retorno sem mascarar falha','Remova o retorno de finally: complete apenas o registro de limpeza.','const marcas=[];\nfunction operar(){\n  try{throw new Error("falhou");}\n  finally{«marcas.push("limpo")»;}\n}\nlet mensagem;try{operar();}catch(e){mensagem=e.message;}\nconst resultado=[mensagem,marcas];',['falhou',['limpo']],'finally deve limpar; um return ali poderia suprimir a exceção.');
tc('Erro agregado de parser por linha','Colete números de linha de todos os JSONs inválidos.','let resultado;\ntry{\n  const erros=[];["1","?","{"].forEach((texto,i)=>{\n    try{JSON.parse(texto);}catch(e){erros.push({linha:i+1,causa:e.name});}\n  });\n  if(erros.length)throw new AggregateError(«erros»,"linhas inválidas");\n}catch(e){resultado=e.errors.map(x=>x.linha);}',[2,3],'Os erros agregados podem conter objetos estruturados com o contexto de cada linha.');
tc('Sinalizar falha de aquisição','Não tente liberar um recurso que nunca foi adquirido.','let recurso,fechamentos=0,mensagem;\ntry{throw new Error("abrir falhou");}\ncatch(e){mensagem=e.message;}\nfinally{if(«recurso !== undefined»)fechamentos++;}\nconst resultado=[mensagem,fechamentos];',['abrir falhou',0],'A limpeza verifica se a aquisição realmente produziu um recurso.');
tc('Isolar falhas de observadores','Notifique todos os observadores e agregue falhas no fim.','const marcas=[],erros=[];\nconst observadores=[()=>marcas.push(1),()=>{throw new Error("obs");},()=>marcas.push(3)];\nfor(const fn of observadores){try{fn();}catch(e){erros.push(«e»);}}\nconst resultado=[marcas,erros.map(e=>e.message)];',[[1,3],['obs']],'Capturar por observador permite que os demais ainda recebam a notificação.');
tc('Rollback com compensação falha','Continue as outras compensações mesmo que uma falhe.','const marcas=[],erros=[];\nconst compensacoes=[()=>marcas.push("A"),()=>{throw new Error("B");},()=>marcas.push("C")];\nwhile(compensacoes.length){\n  try{compensacoes.pop()();}\n  catch(e){erros.push(«e.message»);}\n}\nconst resultado=[marcas,erros];',[['C','A'],['B']],'Falhar ao compensar uma etapa não deve impedir as outras limpezas.');
tc('Traduzir só erro conhecido','Converta o erro de parser em domínio e preserve erros de programação.','function adaptar(fn){\n  try{return fn();}\n  catch(e){if(e instanceof SyntaxError)throw new Error("documento inválido",{cause:e});«throw e»;}\n}\nlet resultado;\ntry{adaptar(()=>{throw new TypeError("bug");});}\ncatch(e){resultado=[e.name,e.message];}',['TypeError','bug'],'A tradução seletiva evita esconder erros inesperados como se fossem entrada inválida.');
tc('Propagação após limpeza de três níveis','Complete a marca do nível intermediário durante o desenrolar da pilha.','const resultado=[];\ntry{\n  try{\n    try{throw new Error("x");}finally{resultado.push(1);}\n  }finally{resultado.push(«2»);}\n}catch{resultado.push(3);}',[1,2,3],'A limpeza ocorre do bloco mais interno para o externo.');
tc('Evitar lançamento em serialização de log','Proteja JSON.stringify para que o tratamento continue.','const circular={};circular.eu=circular;\nlet resultado;\ntry{throw circular;}catch(e){\n  try{resultado=JSON.stringify(e);}\n  catch{resultado=«"[não serializável]"»;}\n}','[não serializável]','O registro de uma falha não deve produzir outra falha não tratada.');
tc('Remover registro temporário','Garanta que a entrada temporária saia do Map após uma exceção.','const ativos=new Map();\ntry{ativos.set("job",true);throw new Error("x");}\ncatch{}\nfinally{«ativos.delete("job")»;}\nconst resultado=ativos.size;',0,'delete limpa a chave específica sem remover entradas de outras operações.');
tc('Separar erro recuperável de defeito','Retorne fallback somente para a subclasse recuperável.','class Recuperavel extends Error{}\nfunction executar(fn){\n  try{return fn();}\n  catch(e){if(e instanceof Recuperavel)return "fallback";«throw e»;}\n}\nlet falha;try{executar(()=>{throw new Error("defeito");});}catch(e){falha=e.message;}\nconst resultado=[executar(()=>{throw new Recuperavel("temporário");}),falha];',['fallback','defeito'],'A classe de erro define quais falhas podem ser recuperadas com segurança.');
function aa(title,goal,source,expected,hint){add(title,goal+' As operações externas deste exemplo são simuladas localmente.',`async function main() {\n${source.split('\n').map(l=>'  '+l).join('\n')}\n  console.log(JSON.stringify(resultado));\n}\nmain();`,expected,hint);}
group('async-await','easy');
aa('Aguardar número resolvido','Extraia o valor de uma Promise resolvida.','const resultado=«await» Promise.resolve(42);',42,'await suspende a função assíncrona até obter o valor da Promise.');
aa('Declarar função assíncrona','Marque a função que retorna uma Promise automaticamente.','«async» function valor(){return 7;}\nconst resultado=await valor();',7,'Uma função async envolve seu retorno em uma Promise.');
aa('Saudação assíncrona','Aguarde o nome antes de montar a saudação.','const nome=«await» Promise.resolve("Ana");\nconst resultado="Olá, "+nome;','Olá, Ana','Sem await, nome seria uma Promise em vez de texto.');
aa('Somar duas leituras','Aguarde ambas as leituras antes de somar os números.','const a=await Promise.resolve(3);\nconst b=«await» Promise.resolve(5);\nconst resultado=a+b;',8,'As duas variáveis precisam guardar números resolvidos.');
aa('Objeto vindo de Promise','Aguarde o objeto para acessar a propriedade nome.','const usuario=«await» Promise.resolve({nome:"Lia"});\nconst resultado=usuario.nome;','Lia','A propriedade pertence ao objeto resolvido, não à Promise.');
aa('Lista carregada','Aguarde o array e retorne sua quantidade de itens.','const itens=«await» Promise.resolve(["a","b","c"]);\nconst resultado=itens.length;',3,'Após await, os métodos e propriedades do array ficam disponíveis.');
aa('Rejeição capturada','Aguarde a Promise rejeitada dentro do try.','let resultado;\ntry{«await» Promise.reject(new Error("offline"));}\ncatch(e){resultado=e.message;}','offline','await transforma a rejeição em uma exceção capturável naquele ponto.');
aa('Retorno de booleano assíncrono','Complete a declaração de uma arrow async.','const ativo=«async» ()=>true;\nconst resultado=await ativo();',true,'Async também pode ser usado em arrow functions.');
aa('Duas etapas em ordem','Espere a primeira marca antes de registrar a segunda.','const marcas=[];\nconst primeira=Promise.resolve().then(()=>marcas.push("primeira"));\n«await» primeira;\nmarcas.push("segunda");\nconst resultado=marcas;',['primeira','segunda'],'A espera impõe uma dependência entre as etapas.');
aa('Aguardar um valor comum','Observe que await também aceita valores que não são Promises.','const resultado=«await» 12;',12,'Um valor comum é tratado como um valor já resolvido.');
aa('Função async sem return','Aguarde uma função sem retorno explícito e identifique o tipo.','async function executar(){}\nconst valor=«await» executar();\nconst resultado=typeof valor;','undefined','A Promise de uma função sem return resolve com undefined.');
aa('Falha lançada em async','Capture o throw convertido em rejeição pela função async.','async function falhar(){throw new Error("indisponível");}\nlet resultado;\ntry{«await» falhar();}catch(e){resultado=e.message;}','indisponível','throw dentro de async rejeita a Promise retornada.');
aa('Obter JSON simulado','Aguarde o método json de uma resposta simulada.','const resposta={json:async()=>({id:3})};\nconst corpo=«await» resposta.json();\nconst resultado=corpo.id;',3,'A leitura de corpo pode ser uma segunda operação assíncrona.');
aa('Obter texto simulado','Aguarde text antes de converter para maiúsculas.','const resposta={text:async()=>"node"};\nconst texto=«await» resposta.text();\nconst resultado=texto.toUpperCase();','NODE','Transformações de texto acontecem depois da resolução.');
aa('Usar parâmetro em função async','Aguarde o resultado de uma função que dobra o argumento.','async function dobro(n){return n*2;}\nconst resultado=«await» dobro(6);',12,'Argumentos são passados normalmente; o retorno é aguardado.');
aa('Chamada assíncrona aninhada','Espere a função interna antes de aplicar o acréscimo.','async function base(){return 10;}\nasync function total(){return ( «await» base() )+2;}\nconst resultado=await total();',12,'Os parênteses agrupam o valor resolvido antes da soma.');
aa('Fallback com catch','Use valor alternativo quando uma leitura simulada falhar.','async function ler(){throw new Error("ausente");}\nlet resultado;\ntry{resultado=await ler();}\ncatch{resultado=«"padrão"»;}','padrão','O catch define a recuperação da operação aguardada.');
aa('Limpeza assíncrona simples','Aguarde a limpeza antes de observar a marca final.','let limpo=false;\nasync function limpar(){await Promise.resolve();limpo=true;}\n«await» limpar();\nconst resultado=limpo;',true,'Sem aguardar, a observação poderia acontecer antes da limpeza.');
aa('Arrow com retorno de Promise','Aguarde uma arrow que resolve uma string.','const carregar=async()=>"pronto";\nconst resultado=«await» carregar();','pronto','O retorno implícito da arrow async também é envolvido em Promise.');
aa('Extrair por desestruturação','Aguarde o objeto antes de desestruturar o token.','async function autenticar(){return {token:"abc"};}\nconst {token}=«await» autenticar();\nconst resultado=token;','abc','A desestruturação opera sobre o valor retornado pelo await.');
aa('Preservar zero resolvido','Aguarde uma Promise cujo valor é zero, sem aplicar fallback.','const resultado=«await» Promise.resolve(0);',0,'Zero é uma resolução válida.');
aa('Resolver null','Aguarde null e teste explicitamente sua identidade.','const valor=«await» Promise.resolve(null);\nconst resultado=valor===null;',true,'null continua sendo null depois da resolução.');
aa('Decisão após carregar','Aguarde o estoque antes de decidir se há disponibilidade.','const estoque=«await» Promise.resolve(2);\nconst resultado=estoque>0?"disponível":"esgotado";','disponível','A comparação precisa do valor resolvido.');
aa('Percorrer lista resolvida','Carregue a lista antes de percorrê-la.','const valores=«await» Promise.resolve([2,4,6]);\nlet resultado=0;\nfor(const n of valores)resultado+=n;',12,'Uma Promise não é o array que ela representa.');
aa('Classe com método async','Marque o método para que ele possa usar await.','class Repositorio{\n  «async» contar(){return await Promise.resolve(3);}\n}\nconst resultado=await new Repositorio().contar();',3,'Métodos de classe podem ser declarados async.');
aa('Thenable simples','Aguarde um objeto que implementa then.','const thenable={then(resolve){resolve("compatível");}};\nconst resultado=«await» thenable;','compatível','await assimila objetos thenable, além de instâncias nativas de Promise.');
aa('Identificar a Promise retornada','Complete a declaração para que a chamada retorne Promise.','«async» function obter(){return "x";}\nconst p=obter();\nconst resultado=[p instanceof Promise,await p];',[true,'x'],'O chamador recebe a Promise mesmo que o corpo não use await.');
aa('Aguardar atraso local','Use await para aguardar uma Promise resolvida por timer.','const esperar=()=>new Promise(resolve=>setTimeout(()=>resolve("fim"),1));\nconst resultado=«await» esperar();','fim','O timer é local e não depende de rede.');
aa('Encadear depois de await','Aguarde a string antes de retirar seus espaços.','const texto=«await» Promise.resolve("  oi  ");\nconst resultado=texto.trim();','oi','Métodos da string devem ser chamados no valor resolvido.');
aa('Salvar e ler confirmação','Espere uma gravação simulada que devolve o identificador.','const registros=[];\nasync function salvar(nome){registros.push(nome);return registros.length;}\nconst id=«await» salvar("nota");\nconst resultado=[id,registros];',[1,['nota']],'A confirmação vem da Promise retornada por salvar.');

group('async-await','medium');
aa('Carregar recursos em paralelo','Aguarde as duas Promises juntas preservando a ordem de entrada.','const resultado=await «Promise.all»([Promise.resolve("perfil"),Promise.resolve("preferências")]);',['perfil','preferências'],'Promise.all agrega resoluções na ordem do array de entrada.');
aa('Map assíncrono completo','Aguarde todas as Promises criadas pelo map.','async function dobro(n){return n*2;}\nconst resultado=await «Promise.all»([1,2,3].map(dobro));',[2,4,6],'map com callback async produz um array de Promises.');
aa('Laço sequencial','Espere cada operação antes de começar a próxima.','const marcas=[];\nasync function processar(n){marcas.push("início"+n);await Promise.resolve();marcas.push("fim"+n);}\nfor(const n of [1,2]){«await» processar(n);}\nconst resultado=marcas;',['início1','fim1','início2','fim2'],'await dentro de for…of impõe processamento sequencial.');
aa('Falhas parciais com allSettled','Aguarde todos os resultados sem rejeitar o conjunto.','const respostas=await «Promise.allSettled»([Promise.resolve(7),Promise.reject(new Error("x"))]);\nconst resultado=respostas.map(r=>r.status);',['fulfilled','rejected'],'allSettled informa sucesso ou falha de cada operação.');
aa('Rejeição de Promise.all','Capture a rejeição de um dos itens de all.','let resultado;\ntry{await «Promise.all»([Promise.resolve(1),Promise.reject(new Error("item2"))]);}\ncatch(e){resultado=e.message;}','item2','Uma rejeição basta para rejeitar Promise.all.');
aa('Primeiro sucesso com any','Ignore uma rejeição e obtenha a primeira resolução bem-sucedida.','const resultado=await «Promise.any»([Promise.reject("falha"),Promise.resolve("ok")]);','ok','any só rejeita quando todas as entradas rejeitam.');
aa('Corrida de Promises','Use race para adotar o primeiro resultado liquidado.','const pendente=new Promise(()=>{});\nconst resultado=await «Promise.race»([Promise.resolve("rápido"),pendente]);','rápido','race adota a primeira resolução ou rejeição.');
aa('Dependência entre consultas','Aguarde o usuário antes de consultar suas tarefas.','async function usuario(){return {id:4};}\nasync function tarefas(id){return ["tarefa-"+id];}\nconst u=await usuario();\nconst resultado=«await» tarefas(u.id);',['tarefa-4'],'Operações dependentes precisam do valor da etapa anterior.');
aa('Status HTTP não é rejeição automática','Lance erro ao receber uma resposta simulada com ok false.','const buscar=async()=>({ok:false,status:404,json:async()=>({})});\nlet resultado;\ntry{\n  const resposta=await buscar();\n  if(!resposta.ok) «throw new Error("HTTP " + resposta.status)»;\n  resultado=await resposta.json();\n}catch(e){resultado=e.message;}','HTTP 404','Uma resposta HTTP de erro pode resolver normalmente; valide o status explicitamente.');
aa('Await no try para capturar','Aguarde dentro do try para que seu catch trate a rejeição.','async function origem(){throw new Error("x");}\nasync function protegido(){\n  try{return «await» origem();}\n  catch{return "recuperado";}\n}\nconst resultado=await protegido();','recuperado','Retornar a Promise sem await faria a rejeição escapar desse catch.');
aa('Finally aguardado','Espere a limpeza antes de concluir a função.','const marcas=[];\nasync function limpar(){await Promise.resolve();marcas.push("limpo");}\nasync function usar(){try{return "ok";}finally{«await» limpar();}}\nconst valor=await usar();\nconst resultado=[valor,marcas];',['ok',['limpo']],'A Promise de usar só resolve depois do finally assíncrono terminar.');
aa('Contar resultados bem-sucedidos','Filtre os resultados de allSettled por status.','const rs=await Promise.allSettled([Promise.resolve(1),Promise.reject("x"),Promise.resolve(3)]);\nconst resultado=rs.filter(r=>«r.status === "fulfilled"»).length;',2,'Somente os fulfilled têm um resultado bem-sucedido.');
aa('Filtrar com predicado assíncrono','Aguarde os testes antes de filtrar os valores originais.','const valores=[1,2,3,4];\nconst testes=await Promise.all(valores.map(async n=>n%2===0));\nconst resultado=valores.filter((n,i)=>«testes[i]»);',[2,4],'filter não aguarda callbacks async; resolva os booleanos separadamente.');
aa('Reduce sequencial assíncrono','Aguarde o acumulador que é uma Promise.','const resultado=await [1,2,3].reduce(async(acumulado,n)=>{\n  const total=«await» acumulado;\n  return total+n;\n},Promise.resolve(0));',6,'Cada etapa do reduce recebe a Promise retornada pela etapa anterior.');
aa('Fallback por consulta','Recupere uma rejeição individual antes de agregar os resultados.','const a=Promise.resolve("A");\nconst b=Promise.reject(new Error("B")).catch(()=>«"padrão"»);\nconst resultado=await Promise.all([a,b]);',['A','padrão'],'O catch individual converte a falha em uma resolução de fallback.');
aa('Ordenação preservada por all','Resolva manualmente a segunda Promise primeiro e mantenha a ordem de entrada.','let liberarA,liberarB;\nconst a=new Promise(r=>liberarA=r),b=new Promise(r=>liberarB=r);\nconst conjunto=Promise.all([a,b]);\nliberarB("B");liberarA("A");\nconst resultado=«await» conjunto;',['A','B'],'A ordem de término não muda a ordem dos valores de Promise.all.');
aa('Paginação dependente','Aguarde cada página antes de descobrir a próxima.','const paginas={1:{itens:["a"],proxima:2},2:{itens:["b"],proxima:null}};\nasync function ler(n){return paginas[n];}\nconst resultado=[];let pagina=1;\nwhile(pagina!==null){\n  const dados=«await» ler(pagina);\n  resultado.push(...dados.itens);pagina=dados.proxima;\n}',['a','b'],'A próxima página só fica conhecida depois da resposta atual.');
aa('Tentativa assíncrona repetida','Aguarde a operação dentro de cada tentativa.','let chamadas=0,resultado;\nasync function operar(){if(++chamadas<2)throw new Error("temporário");return "ok";}\nfor(let i=0;i<3;i++){\n  try{resultado=«await» operar();break;}\n  catch(e){if(i===2)throw e;}\n}\nresultado=[resultado,chamadas];',['ok',2],'A rejeição precisa ocorrer dentro do try da tentativa correspondente.');
aa('Timeout simulado determinístico','Capture a rejeição que vence uma corrida com uma operação pendente.','const operacao=new Promise(()=>{});\nconst limite=Promise.reject(new Error("tempo excedido"));\nlet resultado;\ntry{await «Promise.race»([operacao,limite]);}\ncatch(e){resultado=e.message;}','tempo excedido','O timeout está simulado como uma rejeição imediata; race não cancela a operação perdedora.');
aa('Retornar Promise sem perder resultado','Retorne a Promise de uma dependência e aguarde na camada externa.','async function ler(){return 8;}\nasync function repassar(){«return ler()»;}\nconst resultado=await repassar();',8,'A Promise externa assimila o resultado da Promise retornada.');
aa('For await sobre Promises','Percorra valores resolvidos com for await…of.','const resultado=[];\nfor «await» (const n of [Promise.resolve(2),Promise.resolve(4)]){resultado.push(n);} ',[2,4],'for await aguarda cada item do iterável.');
aa('Gerador assíncrono simples','Declare o gerador que aguarda antes de produzir cada item.','«async» function* gerar(){yield await Promise.resolve("a");yield "b";}\nconst resultado=[];\nfor await(const item of gerar())resultado.push(item);',['a','b'],'Um gerador assíncrono combina async com function*.');
aa('Aguardar método da instância','Espere a atualização antes de consultar o estado.','class Contador{n=0;async somar(){await Promise.resolve();this.n++;}}\nconst c=new Contador();\n«await» c.somar();\nconst resultado=c.n;',1,'A atualização ocorre depois da suspensão dentro do método.');
aa('Fechar após falha assíncrona','Execute a limpeza no finally e preserve a mensagem original.','let limpo=false,mensagem;\nasync function fechar(){limpo=true;}\ntry{await Promise.reject(new Error("falha"));}\ncatch(e){mensagem=e.message;}\nfinally{«await» fechar();}\nconst resultado=[mensagem,limpo];',['falha',true],'finally pode aguardar uma operação de liberação de recurso.');
aa('Await e fila de microtarefas','Complete await e observe a ordem das marcas.','const marcas=[];\nasync function executar(){marcas.push("A");«await» Promise.resolve();marcas.push("C");}\nconst p=executar();marcas.push("B");await p;\nconst resultado=marcas;',['A','B','C'],'Mesmo uma Promise já resolvida faz a continuação ocorrer depois da parte síncrona.');
aa('Tratamento de any sem sucessos','Capture AggregateError quando todas as alternativas falham.','let resultado;\ntry{await «Promise.any»([Promise.reject("A"),Promise.reject("B")]);}\ncatch(e){resultado=[e.name,e.errors];}',['AggregateError',['A','B']],'any agrupa as rejeições quando não há nenhum sucesso.');
aa('All de lista vazia','Aguarde all sem tarefas e observe o resultado vazio.','const resultado=await «Promise.all»([]);',[],'Promise.all de array vazio resolve com array vazio.');
aa('Aguardar parse assíncrono inválido','Capture a rejeição do método json da resposta simulada.','const resposta={ok:true,json:async()=>JSON.parse("?")};\nlet resultado;\ntry{resultado=«await» resposta.json();}\ncatch(e){resultado=e.name;}','SyntaxError','Uma resposta bem-sucedida ainda pode ter um corpo impossível de interpretar.');
aa('Preservar contexto com arrow','Use arrow para chamar o método sem perder this.','const repo={prefixo:"id-",async ler(n){return this.prefixo+n;}};\nconst resultado=await Promise.all([1,2].map(«n => repo.ler(n)»));',['id-1','id-2'],'A arrow faz a chamada como método do objeto, preservando o receptor.');
aa('Checar cancelamento antecipado','Não inicie o trabalho quando o sinal já estiver abortado.','const controle=new AbortController();controle.abort();\nasync function operar(sinal){if(sinal.aborted)throw new Error("cancelado");return "feito";}\nlet resultado;\ntry{resultado=«await» operar(controle.signal);}\ncatch(e){resultado=e.message;}','cancelado','O sinal pode estar abortado antes da operação começar.');

group('async-await','hard');
aa('Concorrência limitada por workers','Aguarde cada trabalho dentro do worker, mantendo no máximo dois ativos.','let ativo=0,pico=0,cursor=0;const saidas=[];\nasync function tarefa(n){ativo++;pico=Math.max(pico,ativo);await Promise.resolve();ativo--;return n*2;}\nasync function worker(){\n  while(cursor<4){const i=cursor++;saidas[i]=«await» tarefa(i+1);}\n}\nawait Promise.all([worker(),worker()]);\nconst resultado=[saidas,pico];',[[2,4,6,8],2],'Cada worker só pega o próximo índice depois de aguardar sua tarefa atual.');
aa('Mutex com fila de Promises','Aguarde a posse anterior antes de entrar na região crítica.','let fila=Promise.resolve(),valor=0;\nasync function incrementar(){\n  const anterior=fila;let liberar;fila=new Promise(r=>liberar=r);\n  await anterior;\n  try{const n=valor;«await» Promise.resolve();valor=n+1;}finally{liberar();}\n}\nawait Promise.all([incrementar(),incrementar(),incrementar()]);\nconst resultado=valor;',3,'A fila serializa a região crítica apesar das suspensões internas.');
aa('Deduplicar requisições em voo','Guarde a Promise antes de aguardar para compartilhar uma operação simultânea.','let chamadas=0;const cache=new Map();\nasync function origem(){chamadas++;await Promise.resolve();return "valor";}\nfunction carregar(chave){\n  if(!cache.has(chave))cache.set(chave,«origem()»);\n  return cache.get(chave);\n}\nconst valores=await Promise.all([carregar("a"),carregar("a")]);\nconst resultado=[valores,chamadas];',[['valor','valor'],1],'Armazenar a Promise em voo impede iniciar uma segunda operação igual.');
aa('Remover Promise rejeitada do cache','Permita nova tentativa excluindo a entrada após rejeição.','let chamadas=0;const cache=new Map();\nasync function origem(){if(++chamadas===1)throw new Error("x");return "ok";}\nfunction carregar(){\n  if(!cache.has("a"))cache.set("a",origem().catch(e=>{«cache.delete("a")»;throw e;}));\n  return cache.get("a");\n}\ntry{await carregar();}catch{}\nconst resultado=[await carregar(),chamadas];',['ok',2],'Uma falha não deve permanecer memorizada quando a política permite tentar novamente.');
aa('Ignorar resposta desatualizada','Atualize a tela apenas quando a resposta pertence à solicitação mais recente.','let versao=0,tela="";\nasync function buscar(p){const minha=++versao;const texto=await p;if(«minha === versao»)tela=texto;}\nlet liberar;const antiga=new Promise(r=>liberar=r);\nconst a=buscar(antiga);await buscar(Promise.resolve("nova"));liberar("antiga");await a;\nconst resultado=tela;','nova','Um número de versão impede que uma resposta antiga sobrescreva uma nova.');
aa('Race não cancela perdedora','Aguarde explicitamente a operação perdedora para observar seu efeito posterior.','let liberar,feito=false;\nconst lenta=new Promise(r=>liberar=r).then(()=>{feito=true;return "lenta";});\nconst vencedor=await Promise.race([Promise.resolve("rápida"),lenta]);\nconst antes=feito;liberar();«await» lenta;\nconst resultado=[vencedor,antes,feito];',['rápida',false,true],'Promise.race escolhe um resultado, mas não interrompe as outras operações.');
aa('Backoff com relógio simulado','Aguarde o atraso exponencial registrado entre tentativas.','const atrasos=[];let chamadas=0,valor;\nasync function esperar(ms){atrasos.push(ms);}\nasync function operar(){if(++chamadas<3)throw new Error("temporário");return "ok";}\nfor(let i=0;i<3;i++){\n  try{valor=await operar();break;}\n  catch(e){if(i===2)throw e;await esperar(«100 * 2 ** i»);}\n}\nconst resultado=[valor,atrasos];',['ok',[100,200]],'O relógio é simulado: os atrasos crescem 100, 200, 400 sem esperar tempo real.');
aa('Retry seletivo assíncrono','Não repita falhas permanentes, mesmo que restem tentativas.','let chamadas=0,resultado;\nasync function operar(){chamadas++;const e=new Error("negado");e.code="EACCES";throw e;}\ntry{for(let i=0;i<3;i++){\n  try{await operar();break;}catch(e){if(e.code!=="EAGAIN"||i===2)«throw e»;}\n}}catch(e){resultado=[e.code,chamadas];}',['EACCES',1],'Só erros classificados como temporários justificam repetição automática.');
aa('Abortar durante operação pendente','Conecte o sinal ao reject da Promise e remova o listener.','const controle=new AbortController();\nfunction operar(sinal){return new Promise((resolve,reject)=>{\n  const abortar=()=>{sinal.removeEventListener("abort",abortar);reject(new Error("cancelado"));};\n  sinal.addEventListener(«"abort"»,abortar,{once:true});\n});}\nconst p=operar(controle.signal);controle.abort();\nlet resultado;try{await p;}catch(e){resultado=e.message;}','cancelado','Operações canceláveis precisam observar o sinal e rejeitar cooperativamente.');
aa('Propagar motivo de abort','Rejeite usando exatamente a razão fornecida pelo chamador.','const c=new AbortController();c.abort(new Error("usuário saiu"));\nasync function operar(sinal){if(sinal.aborted)throw «sinal.reason»;return 1;}\nlet resultado;try{await operar(c.signal);}catch(e){resultado=e.message;}','usuário saiu','signal.reason preserva o motivo do cancelamento.');
aa('Backpressure no gerador','Espere o consumo de cada item antes de solicitar o próximo.','const marcas=[];\nasync function* gerar(){for(const n of [1,2]){marcas.push("produz"+n);yield n;}}\nfor await(const n of gerar()){await Promise.resolve();marcas.push(«"consome" + n»);}\nconst resultado=marcas;',['produz1','consome1','produz2','consome2'],'for await pede o próximo item depois de concluir o corpo atual.');
aa('Fechar stream simulado no break','Aguarde a limpeza do gerador ao interromper o consumo.','let fechado=false;\nasync function* stream(){try{yield 1;yield 2;}finally{«await» Promise.resolve();fechado=true;}}\nfor await(const n of stream()){break;}\nconst resultado=fechado;',true,'O encerramento de um iterador async pode incluir limpeza assíncrona aguardada.');
aa('Erro em gerador assíncrono','Capture a rejeição produzida durante a próxima leitura.','async function* gerar(){yield 1;throw new Error("stream falhou");}\nconst resultado=[];\ntry{for await(const n of gerar())resultado.push(n);}\ncatch(e){resultado.push(«e.message»);}',[1,'stream falhou'],'O catch envolve o consumo porque a falha acontece ao pedir o próximo item.');
aa('Juntar chunks de texto','Aguarde cada fragmento e preserve a ordem do fluxo.','async function* chunks(){yield "No";yield Promise.resolve("de");yield ".js";}\nlet resultado="";\nfor «await» (const chunk of chunks())resultado+=chunk;','Node.js','O consumo assíncrono reúne os fragmentos na ordem de produção.');
aa('Processar lotes paralelos em sequência','Aguarde um lote inteiro antes de iniciar o seguinte.','const marcas=[];\nasync function executar(n){marcas.push("i"+n);await Promise.resolve();marcas.push("f"+n);}\nfor(const lote of [[1,2],[3]]){await «Promise.all»(lote.map(executar));}\nconst resultado=marcas;',['i1','i2','f1','f2','i3','f3'],'Cada lote tem paralelismo interno, mas há uma barreira entre lotes.');
aa('Commit após validar todas as etapas','Publique o estado somente quando todas as validações assíncronas passarem.','let publicado="antigo";\nasync function validarA(){return true;}\nasync function validarB(){throw new Error("inválido");}\ntry{\n  await «Promise.all»([validarA(),validarB()]);\n  publicado="novo";\n}catch{}\nconst resultado=publicado;','antigo','O commit fica depois da barreira de validação.');
aa('Rollback assíncrono em ordem inversa','Aguarde cada compensação antes de executar a anterior.','const marcas=[];\nconst desfazer=[async()=>{await Promise.resolve();marcas.push("A");},async()=>{await Promise.resolve();marcas.push("B");}];\ntry{throw new Error("falha");}\ncatch{while(desfazer.length)«await» desfazer.pop()();}\nconst resultado=marcas;',['B','A'],'Compensações dependentes precisam ser aguardadas em ordem inversa.');
aa('Recursos com aquisição parcial','Libere apenas os recursos adquiridos quando a próxima aquisição falhar.','const marcas=[],recursos=[];\nasync function abrir(nome){if(nome==="C")throw new Error("falha");return {fechar:async()=>marcas.push(nome)};}\ntry{for(const nome of ["A","B","C"])recursos.push(await abrir(nome));}\ncatch{}\nfinally{while(recursos.length)«await» recursos.pop().fechar();}\nconst resultado=marcas;',['B','A'],'O recurso que falhou ao abrir nunca entrou na pilha de limpeza.');
aa('Coletar todas as falhas de lote','Use allSettled e extraia as razões das rejeições.','const rs=await Promise.allSettled([Promise.reject(new Error("A")),Promise.resolve(2),Promise.reject(new Error("C"))]);\nconst resultado=rs.filter(r=>r.status==="rejected").map(r=>«r.reason.message»);',['A','C'],'Resultados rejeitados de allSettled expõem reason, não value.');
aa('Limpeza falha sem perder operação','Agregue falha de trabalho e falha de limpeza assíncrona.','let resultado;\ntry{\n  let original;\n  try{await Promise.reject(new Error("trabalho"));}catch(e){original=e;}\n  try{await Promise.reject(new Error("fechar"));}\n  catch(e){throw new AggregateError(«[original,e]»,"dupla falha");}\n}catch(e){resultado=e.errors.map(e=>e.message);}',['trabalho','fechar'],'Agregar os erros evita que a limpeza esconda a falha inicial.');
aa('Pausar fila depois de falha','Recupere a fila para permitir a próxima tarefa, sem apagar a falha do chamador.','let fila=Promise.resolve();\nfunction adicionar(fn){\n  const atual=fila.then(fn);\n  fila=atual.catch(()=>undefined);\n  return «atual»;\n}\nlet primeira;try{await adicionar(async()=>{throw new Error("A");});}catch(e){primeira=e.message;}\nconst resultado=[primeira,await adicionar(async()=>"B")];',['A','B'],'O chamador recebe a Promise original; a fila interna recebe uma recuperação.');
aa('Cache com expiração simulada','Busque novamente quando o relógio ultrapassar a validade.','let agora=0,chamadas=0,cache;\nasync function origem(){return ++chamadas;}\nasync function ler(){\n  if(cache&&agora<cache.expira)return cache.valor;\n  const valor=await origem();cache={valor,expira:agora+10};return valor;\n}\nconst a=await ler();agora=5;const b=await ler();agora=11;\nconst c=«await» ler();\nconst resultado=[a,b,c,chamadas];',[1,1,2,2],'O relógio é controlado pelo exemplo e permite verificar a expiração sem espera real.');
aa('Não guardar rejeições como sucesso','Armazene no cache somente após o await bem-sucedido.','let chamadas=0,cache;\nasync function origem(){if(++chamadas===1)throw new Error("x");return 9;}\nasync function ler(){\n  if(cache!==undefined)return cache;\n  cache=«await» origem();return cache;\n}\ntry{await ler();}catch{}\nconst resultado=[await ler(),await ler(),chamadas];',[9,9,2],'Se await rejeitar, a atribuição ao cache não acontece.');
aa('Semaphore liberado em finally','Libere a vaga mesmo quando a tarefa assíncrona falha.','let vagas=1;\nasync function executar(fn){\n  if(!vagas)throw new Error("lotado");vagas--;\n  try{return await fn();}\n  finally{«vagas++»;}\n}\ntry{await executar(async()=>{throw new Error("x");});}catch{}\nconst resultado=[await executar(async()=>"ok"),vagas];',['ok',1],'O finally evita que uma falha deixe uma vaga permanentemente ocupada.');
aa('Promisificar callback de erro primeiro','Rejeite a Promise quando o callback receber um erro.','function origem(cb){cb(new Error("arquivo"));}\nfunction ler(){return new Promise((resolve,reject)=>{\n  origem((erro,valor)=>{if(erro){«reject(erro)»;return;}resolve(valor);});\n});}\nlet resultado;try{await ler();}catch(e){resultado=e.message;}','arquivo','A convenção de callback usa o primeiro argumento para erro e o segundo para valor.');
aa('Promisificar callback bem-sucedido','Resolva a Promise com o segundo argumento do callback.','function origem(cb){cb(null,"conteúdo");}\nfunction ler(){return new Promise((resolve,reject)=>{\n  origem((erro,valor)=>{if(erro)reject(erro);else «resolve(valor)»;});\n});}\nconst resultado=await ler();','conteúdo','O valor do callback precisa resolver a Promise para ser acessível por await.');
aa('A primeira liquidação prevalece','Complete a primeira resolução e observe que as posteriores são ignoradas.','const p=new Promise((resolve,reject)=>{\n  «resolve("primeiro")»;\n  reject(new Error("tarde"));resolve("último");\n});\nconst resultado=await p;','primeiro','Uma Promise só muda de pendente para liquidada uma vez.');
aa('Circuit breaker simples','Pare de chamar a origem depois de duas falhas consecutivas.','let falhas=0,chamadas=0;\nasync function origem(){chamadas++;throw new Error("origem");}\nasync function protegido(){\n  if(falhas>=2)throw new Error("circuito aberto");\n  try{const r=await origem();falhas=0;return r;}\n  catch(e){«falhas++»;throw e;}\n}\nconst mensagens=[];for(let i=0;i<3;i++){try{await protegido();}catch(e){mensagens.push(e.message);}}\nconst resultado=[mensagens,chamadas];',[['origem','origem','circuito aberto'],2],'A terceira chamada é bloqueada antes de alcançar a origem.');
aa('Recursão assíncrona em árvore','Aguarde as contagens dos filhos antes de reduzir seus valores.','async function contar(no){\n  const filhos=await «Promise.all»((no.filhos||[]).map(contar));\n  return 1+filhos.reduce((a,b)=>a+b,0);\n}\nconst resultado=await contar({filhos:[{filhos:[{}]},{}]});',4,'A redução precisa de números resolvidos, não de Promises.');
aa('Deduplicação com liberação garantida','Remova o trabalho em voo depois da resolução para permitir um novo ciclo.','const pendentes=new Map();let chamadas=0;\nasync function origem(){chamadas++;await Promise.resolve();return chamadas;}\nfunction carregar(){\n  if(!pendentes.has("x")){\n    const p=origem().finally(()=>«pendentes.delete("x")»);pendentes.set("x",p);\n  }\n  return pendentes.get("x");\n}\nconst primeira=await Promise.all([carregar(),carregar()]);\nconst segunda=await carregar();\nconst resultado=[primeira,segunda,chamadas];',[[1,1],2,2],'O mapa compartilha apenas operações em voo; finally encerra o ciclo de deduplicação.');

for(const t of ['return','try-catch','async-await'])for(const l of ['easy','medium','hard']){
 const group=records.filter(e=>e.topic===t&&e.level===l);
 if(group.length!==30)throw Error(`${t}/${l}: ${group.length}, esperado 30`);
}
